module tb_TopModule;

    reg p1a, p1b, p1c, p1d;
    reg p2a, p2b, p2c, p2d;
    wire p1y, p2y;

    TopModule dut (
        .p1a(p1a), .p1b(p1b), .p1c(p1c), .p1d(p1d),
        .p2a(p2a), .p2b(p2b), .p2c(p2c), .p2d(p2d),
        .p1y(p1y), .p2y(p2y)
    );

    integer i;
    reg error;

    initial begin
        error = 0;
        {p1a, p1b, p1c, p1d} = 4'b0;
        {p2a, p2b, p2c, p2d} = 4'b0;
        #10;

        // Test all 16 combinations for p1
        for (i = 0; i < 16; i = i + 1) begin
            {p1a, p1b, p1c, p1d} = i[3:0];
            #10;
            if (p1y !== ~(&i[3:0])) begin
                $display("FAIL: p1 inputs %b, expected %b, got %b", i[3:0], ~(&i[3:0]), p1y);
                error = 1;
            end
        end

        // Test all 16 combinations for p2
        for (i = 0; i < 16; i = i + 1) begin
            {p2a, p2b, p2c, p2d} = i[3:0];
            #10;
            if (p2y !== ~(&i[3:0])) begin
                $display("FAIL: p2 inputs %b, expected %b, got %b", i[3:0], ~(&i[3:0]), p2y);
                error = 1;
            end
        end

        if (error) begin
            $display("SELFTEST FAIL: Errors detected.");
        end else begin
            $display("SELFTEST PASS");
        end
        $finish;
    end

endmodule
